@import url("https://fonts.googleapis.com/css2?family=Newsreader:wght@400;500&display=swap");
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&display=swap");
@import url("https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500&display=swap");
@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
  Cream editorial: a warm reading room for AI products, assistants and
  writing tools. The page is cream paper, the ink is warm near-black, the
  headings are a serif set at book weight and the interface speaks in a
  clean sans. One terracotta marks the action you came to take. Depth comes
  from tone, not shadow: oat cards on cream, and a dark warm panel for code.
*/

:root {
  /* ─── Ground: cream paper, warm ink ─── */
  --background: oklch(0.982 0.005 95.1);
  --foreground: oklch(0.191 0.002 106.6);

  --card: oklch(0.966 0.009 100);                /* oat card, one tone under the page */
  --card-foreground: oklch(0.191 0.002 106.6);

  --popover: oklch(0.993 0.003 95);              /* menus float as the lightest paper */
  --popover-foreground: oklch(0.191 0.002 106.6);

  /* ─── Primary: terracotta, deep enough for white type ─── */
  --primary: oklch(0.57 0.135 39);
  --primary-foreground: oklch(1 0 0);
  --primary-hover: oklch(0.53 0.13 39);
  --primary-active: oklch(0.49 0.12 39);
  --primary-text: oklch(0.55 0.135 39);          /* terracotta as text on cream: 4.8:1 */
  --primary-wash: oklch(0.57 0.135 39 / 0.1);
  --primary-line: oklch(0.57 0.135 39 / 0.35);
  --clay: oklch(0.672 0.131 38.8);               /* the lighter brand clay, for large marks and charts */

  --secondary: oklch(0.948 0.011 95.2);          /* oat: quiet buttons, segmented trays, chips */
  --secondary-foreground: oklch(0.191 0.002 106.6);

  --muted: oklch(0.924 0.014 97.5);              /* tracks and wells */
  --muted-foreground: oklch(0.478 0.006 95.2);

  --accent: oklch(0.948 0.011 95.2);             /* hover rows */
  --accent-foreground: oklch(0.191 0.002 106.6);

  --destructive: oklch(0.53 0.17 26);
  --destructive-foreground: oklch(1 0 0);

  --success: oklch(0.52 0.09 160);
  --success-foreground: oklch(1 0 0);
  --warning: oklch(0.772 0.121 67.4);
  --warning-foreground: oklch(0.191 0.002 106.6);
  --info: oklch(0.52 0.09 249);
  --info-foreground: oklch(1 0 0);

  --border: oklch(0.191 0.002 106.6 / 0.1);      /* the hairline: warm ink at one tenth */
  --input: oklch(0.924 0.014 97.5);              /* a quiet oat well where a part fills with it */
  --line-strong: oklch(0.853 0.014 97.5);        /* field edges and outline buttons */
  --ring: oklch(0.57 0.135 39 / 0.4);
  --radius: 0.625rem;
  /* Radius by size, stepped from --radius the way the catalog derives it:
     checkboxes and chips, buttons and fields, menus, cards, dialogs. */
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.625rem;
  --radius-xl: 0.875rem;
  --radius-2xl: 1.125rem;

  /* ─── Ink ladder ─── */
  --foreground-secondary: oklch(0.359 0.005 106.7);
  --foreground-disabled: oklch(0.75 0.013 96.5);
  --control: oklch(0.75 0.013 96.5);             /* unchecked box edges */
  --field: oklch(0.993 0.003 95);
  --thumb: oklch(1 0 0);
  --scrim: oklch(0.191 0.002 106.6 / 0.4);

  /* ─── Code: the dark warm product panel ─── */
  --code: oklch(0.214 0.002 67.7);
  --code-foreground: oklch(0.948 0.011 95.2);
  --code-header: oklch(0.257 0.006 78.2);
  --code-muted: oklch(0.696 0.011 87.5);
  --code-inline: oklch(0.924 0.014 97.5 / 0.8);
  --syntax-keyword: oklch(0.74 0.12 39);
  --syntax-string: oklch(0.8 0.08 160);
  --syntax-fn: oklch(0.8 0.08 249);
  --syntax-comment: oklch(0.62 0.01 90);

  /* ─── Callout tints ─── */
  --success-tint: oklch(0.52 0.09 160 / 0.1);
  --success-text: oklch(0.44 0.08 160);
  --warning-tint: oklch(0.772 0.121 67.4 / 0.16);
  --warning-text: oklch(0.47 0.09 60);
  --info-tint: oklch(0.52 0.09 249 / 0.1);
  --info-text: oklch(0.45 0.09 249);
  --destructive-tint: oklch(0.53 0.17 26 / 0.08);
  --destructive-text: oklch(0.48 0.16 26);

  --font-sans: "DM Sans", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-serif: "Newsreader", "Iowan Old Style", Georgia, ui-serif, serif;
  --font-mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  /* ─── Depth: colour blocks first. Shadows are rare and warm. ─── */
  --shadow-xs: 0 0.0625rem 0.125rem oklch(0.191 0.002 106.6 / 0.05);
  --shadow-sm: 0 0.0625rem 0.1875rem oklch(0.191 0.002 106.6 / 0.08);
  --shadow-md: 0 0.25rem 0.75rem oklch(0.191 0.002 106.6 / 0.08);
  --shadow-lg: 0 0.5rem 1.5rem -0.25rem oklch(0.191 0.002 106.6 / 0.1);
  --shadow-card: none;
  --shadow-menu: 0 0.5rem 1.5rem -0.375rem oklch(0.191 0.002 106.6 / 0.12), 0 0 0 0.0625rem oklch(0.191 0.002 106.6 / 0.08);
  --shadow-overlay: 0 1.5rem 3rem -0.75rem oklch(0.191 0.002 106.6 / 0.2), 0 0 0 0.0625rem oklch(0.191 0.002 106.6 / 0.08);
  --shadow-thumb: 0 0.0625rem 0.1875rem oklch(0.191 0.002 106.6 / 0.18), 0 0 0 0.0625rem oklch(0.191 0.002 106.6 / 0.06);

  --chart-1: oklch(0.672 0.131 38.8);
  --chart-2: oklch(0.359 0.005 106.7);
  --chart-3: oklch(0.639 0.065 171.5);
  --chart-4: oklch(0.772 0.121 67.4);
  --chart-5: oklch(0.674 0.09 249.3);

  /* --- Motion (soft profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 180ms;
  --transition-duration-base: 240ms;
  --transition-duration-slow: 300ms;
  --ease-out: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-in-out: cubic-bezier(0.77, 0, 0.175, 1);
  --ease-in: cubic-bezier(0.895, 0.03, 0.685, 0.22);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

.dark {
