  --foreground: oklch(0.966 0.009 100);
  --card: oklch(0.236 0.002 67.7);
  --card-foreground: oklch(0.966 0.009 100);
  --popover: oklch(0.268 0.004 106.6);
  --popover-foreground: oklch(0.966 0.009 100);
  --primary: oklch(0.672 0.131 38.8);
  --primary-foreground: oklch(0.191 0.002 106.6);
  --primary-hover: oklch(0.71 0.125 38.8);
  --primary-active: oklch(0.63 0.13 38.8);
  --primary-text: oklch(0.72 0.12 38.8);
  --primary-wash: oklch(0.672 0.131 38.8 / 0.14);
  --primary-line: oklch(0.672 0.131 38.8 / 0.45);
  --clay: oklch(0.672 0.131 38.8);
  --secondary: oklch(0.268 0.004 106.6);
  --secondary-foreground: oklch(0.966 0.009 100);
  --muted: oklch(0.308 0.004 106.6);
  --muted-foreground: oklch(0.75 0.013 96.5);
  --accent: oklch(0.268 0.004 106.6);
  --accent-foreground: oklch(0.966 0.009 100);
  --destructive: oklch(0.66 0.17 26);
  --destructive-foreground: oklch(0.191 0.002 106.6);
  --success: oklch(0.72 0.09 160);
  --success-foreground: oklch(0.191 0.002 106.6);
  --warning: oklch(0.8 0.12 70);
  --warning-foreground: oklch(0.191 0.002 106.6);
  --info: oklch(0.72 0.09 249);
  --info-foreground: oklch(0.191 0.002 106.6);
  --border: oklch(1 0 0 / 0.1);
  --input: oklch(1 0 0 / 0.12);
  --line-strong: oklch(1 0 0 / 0.2);
  --ring: oklch(0.672 0.131 38.8 / 0.5);
  --foreground-secondary: oklch(0.853 0.014 97.5);
  --foreground-disabled: oklch(0.478 0.006 95.2);
  --control: oklch(0.551 0.009 99);
  --field: oklch(0.214 0.002 67.7);
  --thumb: oklch(0.966 0.009 100);
  --scrim: oklch(0 0 0 / 0.6);
  --code: oklch(0.155 0.002 67.7);
  --code-foreground: oklch(0.948 0.011 95.2);
  --code-header: oklch(0.214 0.002 67.7);
  --code-muted: oklch(0.696 0.011 87.5);
  --code-inline: oklch(1 0 0 / 0.08);
  --syntax-keyword: oklch(0.76 0.12 39);
  --syntax-string: oklch(0.8 0.08 160);
  --syntax-fn: oklch(0.8 0.08 249);
  --syntax-comment: oklch(0.62 0.01 90);
  --success-tint: oklch(0.72 0.09 160 / 0.14);
  --success-text: oklch(0.8 0.08 160);
  --warning-tint: oklch(0.8 0.12 70 / 0.14);
  --warning-text: oklch(0.85 0.11 75);
  --info-tint: oklch(0.72 0.09 249 / 0.14);
  --info-text: oklch(0.8 0.08 249);
  --destructive-tint: oklch(0.66 0.17 26 / 0.14);
  --destructive-text: oklch(0.78 0.13 26);
  --shadow-xs: 0 0.0625rem 0.125rem oklch(0 0 0 / 0.3);
  --shadow-sm: 0 0.0625rem 0.1875rem oklch(0 0 0 / 0.35);
  --shadow-md: 0 0.25rem 0.75rem oklch(0 0 0 / 0.4);
  --shadow-lg: 0 0.5rem 1.5rem -0.25rem oklch(0 0 0 / 0.5);
  --shadow-card: none;
  --shadow-menu: 0 0.5rem 1.5rem -0.375rem oklch(0 0 0 / 0.5), 0 0 0 0.0625rem oklch(1 0 0 / 0.1);
  --shadow-overlay: 0 1.5rem 3rem -0.75rem oklch(0 0 0 / 0.6), 0 0 0 0.0625rem oklch(1 0 0 / 0.1);
  --shadow-thumb: 0 0.0625rem 0.1875rem oklch(0 0 0 / 0.4), 0 0 0 0.0625rem oklch(1 0 0 / 0.1);
  --chart-1: oklch(0.672 0.131 38.8);
  --chart-2: oklch(0.853 0.014 97.5);
  --chart-3: oklch(0.7 0.07 171.5);
  --chart-4: oklch(0.8 0.12 70);
  --chart-5: oklch(0.72 0.09 249.3);
